import{_ as l,o as e,c as i,a2 as t}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"Roadmap1","description":"","frontmatter":{},"headers":[],"relativePath":"project/Roadmap.md","filePath":"project/Roadmap.md","lastUpdated":null}'),o={name:"project/Roadmap.md"};function r(p,a,d,n,h,s){return e(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="roadmap1" tabindex="-1">Roadmap<a href="http://www.woshipm.com/pd/3591815.html" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#roadmap1" aria-label="Permalink to &quot;Roadmap[1]&quot;">​</a></h1><p>产品路线图是传达产品战略方向的生动、可视化文档。这些高层次的总结将所有涉及产品管理和产品开发的活动部分结合在一起。他们传达了两个愿望（通过产品愿景）和计划（通过倡议），同时也将产品战略与公司战略联系起来。有效地完成后，产品路线图将传达您正在构建的内容背后的“原因”。</p><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><h3 id="实现以下几点" tabindex="-1">实现以下几点： <a class="header-anchor" href="#实现以下几点" aria-label="Permalink to &quot;实现以下几点：&quot;">​</a></h3><ul><li>描述产品愿景和战略</li><li>提供执行战略的指导文件</li><li>使内部利益相关者保持一致</li><li>促进对选项和方案规划的讨论</li><li>沟通产品开发计划的进展和状态</li><li>帮助向外部利益相关者（包括客户）传达您的战略</li></ul><h3 id="还可帮助" tabindex="-1">还可帮助： <a class="header-anchor" href="#还可帮助" aria-label="Permalink to &quot;还可帮助：&quot;">​</a></h3><ul><li>IT团队可以使用路线图来规划和跟踪架构项目、软件实现和各种其他项目。</li><li>营销团队可以使用路线图来规划从营销策略到内容日历的所有内容。</li><li>业务和业务运营团队可以使用路线图来规划扩展和其他组织范围的目标。</li><li>DevOps可能会使用路线图来更好地连接他们负责整合的组织的各个部分。</li><li>工程团队可以使用路线图来计划冲刺。</li></ul><h2 id="长什么样" tabindex="-1">长什么样 <a class="header-anchor" href="#长什么样" aria-label="Permalink to &quot;长什么样&quot;">​</a></h2><ol><li>产品愿景 你的产品愿景，通常被称为产品愿景宣言或使命宣言，是一个简洁的、高层次的、有抱负的陈述。</li></ol><p>为什么你的产品存在，如果你的产品成功了，世界将会变成怎样？</p><p>它是一盏指路明灯——在当下遥不可及，但却始终代表着预定的方向。</p><p>在Roadmap上阐述产品愿景，一方面有助于我们的产品始终围绕着这个核心价值观而不偏离轨道，另一方面，愿景是我们激励其他部门的重要力量。</p><ol start="2"><li><p>说明 通常需要说明roadmap上时间段的起点和终点分别代表什么意思。时间段不同颜色代表什么意思，比如可以是不同颜色代表不同的技术平台，也可以是代表不同的市场。</p></li><li><p>关键细分 这个关键细分取决于你所在的行业以及你的受众，通常来讲，如果是客户的话，可能是他们在购买你产品的时候主要考虑的几个因素之一。比如手机的话，可以是“米系列”，“红米系列”，汽车的话，可以是“轿车”，“SUV”和“MPV”等。关键细分可以是一层，也可以是多层，但最好不要超过三层。</p></li><li><p>产品信息 通常分为当前在售和未来推出。这里可以在产品名称下面加一些关键特征参数，主打的卖点或关键购买因素等信息。如下图里面12M，1.55μm是CMOS的一些关键特征参数。汽车的话诸如“2.0T，涡轮增压，190马力，国VI，双擎”。这样可以方便受众快速的找到自己关心的产品的进展。</p></li></ol><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>有利且危险：可以帮助产品经理更好地可视化和沟通产品战略，形成健康的权衡。如果他们太过细节和死板，则会造成很多工作浪费，给客户和管理层产生一些无法实现的期望。</p>',15)])])}const u=l(o,[["render",r]]);export{c as __pageData,u as default};
